import React, {useState} from 'react';
import HeaderCM from '../../components/Header/HeaderCM';
import {IconMyReceiptTopRight} from '../../../assets/images';
import {
  Keyboard,
  TouchableOpacity,
  TouchableWithoutFeedback,
  View,
} from 'react-native';
import {useTranslation} from 'react-i18next';

import RenderTabView from './component/tab-view';
import {Icon, Input} from '@ui-kitten/components';
import BottomSheetCM from '../../components/BottomSheet';
import ModalFilter from './component/modal-filter';

const MyReceiptScreen = () => {
  const {t} = useTranslation();
  const [value, setValue] = useState('');
  const [visibleFilter, setVisibleFilter] = useState(false);

  return (
    <TouchableWithoutFeedback onPress={() => Keyboard.dismiss()}>
      <View style={{flex: 1, backgroundColor: '#f9fafe'}}>
        <HeaderCM
          title="MyReceipt"
          useLinearGradient={false}
          style={{backgroundColor: '#C83A1B'}}
          contentStyle={{backgroundColor: '#C83A1B'}}
          renderContentRight={() => (
            <TouchableOpacity onPress={() => false}>
              <IconMyReceiptTopRight width={20} height={20} />
            </TouchableOpacity>
          )}
        />
        <View
          style={{
            backgroundColor: '#C83A1B',
            height: 50,
            paddingLeft: 24,
            paddingRight: 5,
            paddingVertical: 30,
            flexDirection: 'row',
            justifyContent: 'center',
            alignItems: 'center',
            gap: 8,
          }}>
          <Input
            allowFontScaling={false}
            style={{
              backgroundColor: '#fff',
              borderWidth: 0,
              flex: 1,
            }}
            textStyle={{color: 'black'}}
            placeholderTextColor={'#9FB0C7'}
            placeholder={t('SR.searchTicket')}
            value={value}
            status="basic"
            autoFocus
            onChangeText={nextValue => setValue(nextValue)}
            accessoryLeft={
              <TouchableOpacity onPress={() => false}>
                <Icon fill={'#9FB0C7'} name="search" />
              </TouchableOpacity>
            }
            accessoryRight={
              value ? (
                <TouchableOpacity onPress={() => setValue('')}>
                  <Icon name="close-outline" fill="#ffffff" />
                </TouchableOpacity>
              ) : undefined
            }
          />
          <TouchableOpacity
            onPress={() => setVisibleFilter(true)}
            style={{
              width: 30,
              height: 30,
              justifyContent: 'center',
              alignItems: 'center',
            }}>
            <Icon fill={'#fff'} name="funnel-outline" width={25} height={25} />
          </TouchableOpacity>
        </View>
        <BottomSheetCM
          title={t('CM.filter')}
          onClose={() => setVisibleFilter(false)}
          isVisible={visibleFilter}
          renderContent={
            <ModalFilter onClose={() => setVisibleFilter(false)} />
          }
        />
        <RenderTabView />
      </View>
    </TouchableWithoutFeedback>
  );
};

export default MyReceiptScreen;
