import {SceneMap, TabBar, TabView} from 'react-native-tab-view';
import {Font} from '../../../../../constants';
import Lated from './conponent/lated';
import InProgress from './conponent/in-progress';
import Complete from './conponent/complete';
import Draft from './conponent/draft';
import {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {useWindowDimensions} from 'react-native';

const RenderTabView = () => {
  const [index, setIndex] = useState(1);
  const {t} = useTranslation();
  const layout = useWindowDimensions();
  const routes = [
    {key: 'lated', title: t('Trễ hạn')},
    {key: 'inProgress', title: t('Đang thực hiện')},
    {key: 'complete', title: t('Hoàn thành')},
    {key: 'draft', title: t('Nháp')},
  ];
  const renderTabBar = (props: any) => (
    <TabBar
      {...props}
      indicatorStyle={{backgroundColor: '#C83A1B'}}
      style={{backgroundColor: '#fff'}}
      scrollEnabled
      labelStyle={{
        color: '#00204DB2',
        fontFamily: Font.InterRegular400,
        fontSize: 14,
        textAlign: 'center',
      }}
      activeColor="#C83A1B"
    />
  );
  const renderScene = SceneMap({
    lated: Lated,
    inProgress: InProgress,
    complete: Complete,
    draft: Draft,
  });
  return (
    <>
      <TabView
        lazy
        style={{backgroundColor: '#f9fafe'}}
        sceneContainerStyle={{paddingHorizontal: 16, paddingVertical: 10}}
        renderTabBar={renderTabBar}
        navigationState={{index, routes}}
        renderScene={renderScene}
        onIndexChange={setIndex}
        initialLayout={{width: layout.width}}
        swipeEnabled={false}
      />
    </>
  );
};
export default RenderTabView;
